from django.db import transaction
from rest_framework import serializers

from .models import Order, OrderItem


class OrderItemSerializer(serializers.ModelSerializer):
    class Meta:
        model = OrderItem
        fields = ["id", "product", "quantity"]


class OrderSerializer(serializers.ModelSerializer):
    items = OrderItemSerializer(many=True, allow_empty=False)

    class Meta:
        model = Order
        fields = ["id", "customer_name", "created_at", "items"]

    def validate(self, attrs):
        items = attrs.get("items")
        if items is None:
            return attrs
        products = [item["product"].pk for item in items]
        if len(products) != len(set(products)):
            raise serializers.ValidationError({"items": "Each product may appear only once."})
        return attrs

    def create(self, validated_data):
        items_data = validated_data.pop("items")
        with transaction.atomic():
            order = Order.objects.create(**validated_data)
            for data in items_data:
                OrderItem.objects.create(
                    order=order, product=data["product"], quantity=data["quantity"]
                )
        return order

def update(self, instance, validated_data):
    items_data = validated_data.pop("items", None)
    with transaction.atomic():
        for attr, value in validated_data.items():
            setattr(instance, attr, value)
        instance.save()
        if items_data is not None:
            self._sync_items(instance, items_data)
    return instance

def _sync_items(self, order, items_data):
    existing = {item.pk: item for item in order.items.all()}
    keep = []
    for data in items_data:
        item = existing.get(data.get("id"))
        if item is None:
            item = OrderItem(order=order)
        item.product = data["product"]
        item.quantity = data["quantity"]
        item.save()
        keep.append(item.pk)
    order.items.exclude(pk__in=keep).delete()
